package com.backendSupermercado.supermercasdo.modules.reportes.compras.repository;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository;
@Repository public class ReporteComprasRepository { private final NamedParameterJdbcTemplate jdbc; public ReporteComprasRepository(NamedParameterJdbcTemplate j){jdbc=j;} public Page<Map<String,Object>> consultar(String r,Map<String,Object>f,Pageable pg){MapSqlParameterSource p=new MapSqlParameterSource();f.forEach(p::addValue);String w=" WHERE 1=1 ";if(f.get("proveedorId")!=null)w+=" AND pp.id_proveedor=:proveedorId ";if(f.get("estadoPedido")!=null)w+=" AND ep.nombre=:estadoPedido ";String from=" FROM pedido_proveedor pp JOIN proveedor pr ON pr.id_proveedor=pp.id_proveedor LEFT JOIN empresa em ON em.id_proveedor=pr.id_proveedor JOIN estado_pedido ep ON ep.id_estado_pedido=pp.id_estado_pedido ";String s;if(r.equals("pedidos-general")||r.equals("pedidos-pendientes")){if(r.equals("pedidos-pendientes"))w+=" AND LOWER(ep.nombre) IN ('pendiente','parcial') ";s="SELECT pp.id_pedido AS id,pp.fecha_pedido AS fecha,COALESCE(em.razon_social,'Proveedor') AS proveedor,ep.nombre AS estado,pp.fecha_entrega_estimada AS entrega,(SELECT COUNT(*) FROM detalle_pedido_proveedor d WHERE d.id_pedido=pp.id_pedido) AS productos";String g=s+from+w+" ORDER BY pp.fecha_pedido DESC";return page(g,"SELECT COUNT(*)"+from+w,p,pg);}if(r.equals("recepciones-mercaderia")){from=" FROM recepcion_mercaderia rm JOIN pedido_proveedor pp ON pp.id_pedido=rm.id_pedido JOIN proveedor pr ON pr.id_proveedor=pp.id_proveedor LEFT JOIN empresa em ON em.id_proveedor=pr.id_proveedor JOIN estado_recepcion er ON er.id_estado_recepcion=rm.id_estado_recepcion ";s="SELECT rm.id_recepcion AS id,rm.fecha_recepcion AS fecha,COALESCE(em.razon_social,'Proveedor') AS proveedor,er.nombre AS estado,(SELECT COUNT(*) FROM detalle_recepcion d WHERE d.id_recepcion=rm.id_recepcion) AS productos";return page(s+from+" WHERE 1=1 ORDER BY rm.fecha_recepcion DESC","SELECT COUNT(*)"+from+" WHERE 1=1",p,pg);}if(r.equals("compras-proveedor")){String x="SELECT pr.id_proveedor AS id,COALESCE(em.razon_social,'Proveedor') AS proveedor,COUNT(DISTINCT pp.id_pedido) AS pedidos,COALESCE(SUM(dr.cantidad_recibida*dr.precio_unitario),0) AS total FROM pedido_proveedor pp JOIN proveedor pr ON pr.id_proveedor=pp.id_proveedor LEFT JOIN empresa em ON em.id_proveedor=pr.id_proveedor LEFT JOIN recepcion_mercaderia rm ON rm.id_pedido=pp.id_pedido LEFT JOIN detalle_recepcion dr ON dr.id_recepcion=rm.id_recepcion WHERE 1=1 GROUP BY pr.id_proveedor,em.razon_social ORDER BY total DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("productos-comprados")){String x="SELECT p.id_producto AS id,p.codigo_interno AS codigo,p.nombre AS producto,SUM(dr.cantidad_recibida) AS cantidad,SUM(dr.cantidad_recibida*dr.precio_unitario) AS costo FROM detalle_recepcion dr JOIN detalle_pedido_proveedor dp ON dp.id_detalle_pedido=dr.id_detalle_pedido JOIN producto p ON p.id_producto=dp.id_producto GROUP BY p.id_producto,p.codigo_interno,p.nombre ORDER BY costo DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("rentabilidad-compras")){String x="SELECT p.id_producto AS id,p.codigo_interno AS codigo,p.nombre AS producto,AVG(dr.precio_unitario) AS costo, p.precio_venta AS precio, p.precio_venta-AVG(dr.precio_unitario) AS ganancia FROM detalle_recepcion dr JOIN detalle_pedido_proveedor dp ON dp.id_detalle_pedido=dr.id_detalle_pedido JOIN producto p ON p.id_producto=dp.id_producto GROUP BY p.id_producto,p.codigo_interno,p.nombre,p.precio_venta ORDER BY ganancia DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("devoluciones-proveedor")){String x="SELECT dv.id_devolucion AS id,dv.fecha_devolucion AS fecha,COALESCE(em.razon_social,'Proveedor') AS proveedor,ed.nombre AS estado,md.nombre AS motivo,SUM(dd.cantidad) AS cantidad FROM devolucion_proveedor dv JOIN recepcion_mercaderia rm ON rm.id_recepcion=dv.id_recepcion JOIN pedido_proveedor pp ON pp.id_pedido=rm.id_pedido JOIN proveedor pr ON pr.id_proveedor=pp.id_proveedor LEFT JOIN empresa em ON em.id_proveedor=pr.id_proveedor JOIN estado_devolucion ed ON ed.id_estado_devolucion=dv.id_estado_devolucion JOIN detalle_devolucion_proveedor dd ON dd.id_devolucion=dv.id_devolucion JOIN motivo_devolucion md ON md.id_motivo_devolucion=dd.id_motivo_devolucion GROUP BY dv.id_devolucion,dv.fecha_devolucion,em.razon_social,ed.nombre,md.nombre ORDER BY dv.fecha_devolucion DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("cumplimiento-proveedores")){String x="SELECT pr.id_proveedor AS id,COALESCE(em.razon_social,'Proveedor') AS proveedor,COUNT(DISTINCT pp.id_pedido) AS pedidos,COUNT(DISTINCT rm.id_recepcion) AS recepciones FROM proveedor pr LEFT JOIN empresa em ON em.id_proveedor=pr.id_proveedor LEFT JOIN pedido_proveedor pp ON pp.id_proveedor=pr.id_proveedor LEFT JOIN recepcion_mercaderia rm ON rm.id_pedido=pp.id_pedido GROUP BY pr.id_proveedor,em.razon_social ORDER BY pedidos DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("compras-periodo")){String x="SELECT DATE(pp.fecha_pedido) AS fecha,COUNT(DISTINCT pp.id_pedido) AS pedidos,COUNT(DISTINCT pp.id_proveedor) AS proveedores FROM pedido_proveedor pp GROUP BY DATE(pp.fecha_pedido) ORDER BY fecha DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}if(r.equals("abastecimiento-general")){String x="SELECT DATE(pp.fecha_pedido) AS fecha,COUNT(DISTINCT pp.id_pedido) AS pedidos,COUNT(DISTINCT rm.id_recepcion) AS recepciones,COUNT(DISTINCT dv.id_devolucion) AS devoluciones FROM pedido_proveedor pp LEFT JOIN recepcion_mercaderia rm ON rm.id_pedido=pp.id_pedido LEFT JOIN devolucion_proveedor dv ON dv.id_recepcion=rm.id_recepcion GROUP BY DATE(pp.fecha_pedido) ORDER BY fecha DESC";return page(x,"SELECT COUNT(*) FROM ("+x+") q",p,pg);}from=" FROM detalle_pedido_proveedor dp JOIN pedido_proveedor pp ON pp.id_pedido=dp.id_pedido JOIN producto p ON p.id_producto=dp.id_producto LEFT JOIN detalle_recepcion dr ON dr.id_detalle_pedido=dp.id_detalle_pedido ";s="SELECT dp.id_detalle_pedido AS id,p.codigo_interno AS codigo,p.nombre AS producto,dp.cantidad_solicitada AS solicitado,COALESCE(SUM(dr.cantidad_recibida),0) AS recibido,dp.cantidad_solicitada-COALESCE(SUM(dr.cantidad_recibida),0) AS faltante";String g=s+from+w.replace("ep.nombre", "1=1")+" GROUP BY dp.id_detalle_pedido,p.codigo_interno,p.nombre,dp.cantidad_solicitada ORDER BY p.nombre";return page(g,"SELECT COUNT(*) FROM ("+g+") q",p,pg);}
 private Page<Map<String,Object>> page(String s,String c,MapSqlParameterSource p,Pageable pg){s=s.replace("IN ('pendiente','parcial')","IN ('pendiente','parcial','parcialmente_recibido')");c=c.replace("IN ('pendiente','parcial')","IN ('pendiente','parcial','parcialmente_recibido')");String precio="COALESCE((SELECT ppv.precio_venta FROM presentacion_producto ppv WHERE ppv.id_producto=p.id_producto AND ppv.es_principal=TRUE ORDER BY ppv.id_presentacion LIMIT 1),0)";s=s.replace("p.precio_venta",precio).replace(","+precio+" ORDER BY", " ORDER BY");c=c.replace("p.precio_venta",precio).replace(","+precio+" ORDER BY", " ORDER BY");p.addValue("limite",pg.isPaged()?pg.getPageSize():Integer.MAX_VALUE).addValue("offset",pg.isPaged()?pg.getOffset():0);List<Map<String,Object>>d=jdbc.queryForList(s+" LIMIT :limite OFFSET :offset",p);Long n=jdbc.queryForObject(c,p,Long.class);return new PageImpl<>(d,pg,n);} }
